import React from "react";
import { Link } from "react-router-dom";

const Home = () => {
  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-300 to-blue-700 flex flex-col items-center justify-center text-center p-6">
      <h1 className="text-4xl font-bold text-white mb-6">🎮 Online Gamification System</h1>

      <div className="flex flex-col md:flex-row gap-4">
        <Link to="/register">
          <button className="bg-white text-blue-700 px-6 py-3 rounded shadow hover:bg-blue-100">📝 Register</button>
        </Link>
        <Link to="/login">
          <button className="bg-white text-blue-700 px-6 py-3 rounded shadow hover:bg-blue-100">🔐 Login</button>
        </Link>
        <Link to="/leaderboard">
          <button className="bg-white text-blue-700 px-6 py-3 rounded shadow hover:bg-blue-100">🏆 Leaderboard</button>
        </Link>
      </div>
    </div>
  );
};

export default Home;
